// 响应式数据
const activeTab = ref('videos'); // 默认显示图片

// 计算属性
const currentComponent = computed(() => {
  return activeTab.value === 'videos' ? GeneratedVideosView : GeneratedImagesView;
});

// 事件处理函数
const switchTab = (tab) => {
  console.log('Switching to tab:', tab);
  activeTab.value = tab;
};
